                    <span class="icon">💔</span>
                    <span>纯白少女们</span>
                </div>
                <svg class="chevron" id="chevron-heroines" fill="none" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" d="M19 9l-7 7-7-7"></path>
                </svg>
            </div>
