function calculateNextDayInfo(dateStr) {
    const match = dateStr.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
    if (!match) {
        console.error("[MVU Script] Invalid date format for calculation:", dateStr);
        return null;
    }

    const year = parseInt(match[1]);
    const month = parseInt(match[2]);
    const day = parseInt(match[3]);

    const currentDateObj = new Date(year, month - 1, day);
    if (isNaN(currentDateObj.getTime())) {
        console.error("[MVU Script] Invalid date created from:", dateStr);
        return null;
    }

    currentDateObj.setDate(currentDateObj.getDate() + 1);

    const nextYear = currentDateObj.getFullYear();
    const nextMonth = currentDateObj.getMonth() + 1;
    const nextDay = currentDateObj.getDate();
    const nextDayIndex = currentDateObj.getDay();

    const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
    const nextWeekday = weekdays[nextDayIndex];

    const nextDateStr = `${nextYear}年${String(nextMonth).padStart(2, '0')}月${String(nextDay).padStart(2, '0')}日`;

    return { nextDate: nextDateStr, nextWeekday: nextWeekday };
}

function variableUpdateEnded(variables, _out_is_updated) {
    if (!variables?.stat_data?.世界?.当前日期?.[0] || !variables?.stat_data?.世界?.星期几?.[0]) {
        console.error("[MVU Script] Date/Weekday variables missing in stat_data after update.");
        return;
    }
     if (!initialDate || !initialWeekday) {
         console.warn("[MVU Script] Initial Date/Weekday not captured correctly.");
         initialDate = variables.stat_data.世界.当前日期[0];
         initialWeekday = variables.stat_data.世界.星期几[0];
     }

    const finalDate = variables.stat_data.世界.当前日期[0];
    const finalWeekday = variables.stat_data.世界.星期几[0];

    const dayRolloverOccurred = (initialWeekday === '周日' && finalWeekday === '周一');

    if (dayRolloverOccurred) {
        const expectedNextDayInfo = calculateNextDayInfo(initialDate);

        if (!expectedNextDayInfo) {
            console.error("[MVU Script] Could not calculate expected next date from:", initialDate);
            return;
        }

        const expectedNextDate = expectedNextDayInfo.nextDate;
        const expectedNextWeekday = expectedNextDayInfo.nextWeekday;

        let dateNeedsCorrection = (finalDate !== expectedNextDate);
        let weekdayNeedsCorrection = (finalWeekday !== expectedNextWeekday);

        if (dateNeedsCorrection || weekdayNeedsCorrection) {
            console.warn(`[MVU Script] Date/Weekday mismatch after Sun->Mon rollover. AI final: ${finalDate} ${finalWeekday}. Expected: ${expectedNextDate} ${expectedNextWeekday}. Correcting...`);

            variables.stat_data.世界.当前日期[0] = expectedNextDate;
            variables.stat_data.世界.星期几[0] = expectedNextWeekday;

            variables.display_data = variables.display_data || {};
            variables.display_data.世界 = variables.display_data.世界 || {};
            if (dateNeedsCorrection) {
                variables.display_data.世界.当前日期 = `${finalDate}->${expectedNextDate}(脚本修正)`;
            }
             if (weekdayNeedsCorrection) {
                 variables.display_data.世界.星期几 = `${finalWeekday}->${expectedNextWeekday}(脚本修正)`;
             }

             console.log("[MVU Script] Script forced date/weekday update.");
        }
    }

    initialDate = "";
    initialWeekday = "";
}

function parseTimeToNumber(timeStr) {
    if (!timeStr || typeof timeStr !== 'string') return 0;
    const parts = timeStr.split(':');
    if (parts.length !== 2) return 0;
    const hours = parseInt(parts[0]);
    const minutes = parseInt(parts[1]);
    if (isNaN(hours) || isNaN(minutes)) return 0;
    return hours * 100 + minutes;
}

