    <script>
        // 通用折叠函数
        function toggleSection(sectionName) {
            const content = document.getElementById(`content-${sectionName}`);
            const chevron = document.getElementById(`chevron-${sectionName}`);
            if (content && chevron) {
                const isExpanded = content.classList.toggle('expanded');
                chevron.classList.toggle('expanded', isExpanded);
            }
        }

        document.addEventListener('DOMContentLoaded', async () => {
            let characterData = {}; // 用于存储最终的数据

            // 安全地获取路径下的值
            const safeGet = (obj, path, defaultValue = '--') => {
                // 将路径分割成键的数组
                const keys = path.split('.');
                // 使用 reduce 安全地访问嵌套属性
                let result = keys.reduce((acc, key) => {
                    // 如果当前累加器是有效的对象，则访问下一个键
                    if (acc && typeof acc === 'object') {
                        return acc[key];
                    }
                    // 否则返回 undefined
                    return undefined;
                }, obj);

                // 如果结果是 undefined 或 null，返回默认值
                if (result === undefined || result === null) {
                    return defaultValue;
                }

                // 如果结果是数组，取第一个元素，否则直接返回值
                return Array.isArray(result) ? result[0] : result;
            };

            try {
                // **【核心修正】使用更可靠的方式获取数据**
                const currentMessageId = getCurrentMessageId();
                if (!currentMessageId) throw new Error("无法获取当前消息ID。");

                const messageDataArray = getChatMessages(currentMessageId);
                if (!messageDataArray || messageDataArray.length === 0) throw new Error("无法获取消息数据。");
                const gameData = messageDataArray[0].data;

                // 优先使用 stat_data，如果不存在则回退到 display_data
                characterData = gameData.stat_data || gameData.display_data;
                if (!characterData) throw new Error("在消息中未找到 stat_data 或 display_data。");

                // 开始填充数据
                // 更新世界状态
                const worldState = characterData.世界状态 || {};
                document.getElementById('world-time').textContent = safeGet(worldState, '当前时间');
                document.getElementById('world-location').textContent = safeGet(worldState, '当前地点');

                const deviation = parseInt(safeGet(worldState, '剧情偏离度', 0), 10);
                const deviationBar = document.getElementById('deviation-bar');
                const deviationLabel = document.getElementById('deviation-label');
                deviationBar.style.width = `${deviation}%`;
                deviationLabel.textContent = `${deviation}%`;

                // 更新女主角信息
                const heroinesContainer = document.getElementById('content-heroines');
                heroinesContainer.innerHTML = ''; // 清空旧内容

                const heroines = characterData.女主角们 || {};
                for (const name in heroines) {
                    const data = heroines[name];
                    const affection = parseInt(safeGet(data, '好感度', 0), 10);
                    const corruption = parseInt(safeGet(data, '恶堕值', 0), 10);

                    const affectionPercent = ((affection + 100) / 200) * 100;
                    const corruptionPercent = corruption;

                    const cardHTML = `
                        <div class="heroine-card halftone-bg" id="heroine-${name}">
                            <div class="heroine-header" onclick="toggleSection('heroine-${name}')">
                                <span class="heroine-name">${name}</span>
                                <svg class="chevron" id="chevron-heroine-${name}" fill="none" viewBox="0 0 24 24">
                                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="3" d="M19 9l-7 7-7-7"></path>
                                </svg>
                            </div>
                            <div class="heroine-content" id="content-heroine-${name}">
                                <div class="info-item">
                                    <span class="info-name">关系阶段</span>
                                    <span class="info-value">${safeGet(data, '关系阶段')}</span>
                                </div>
                                <div class="info-item">
                                    <span class="info-name">关系动向</span>
                                    <span class="info-value">${safeGet(data, '关系动向')}</span>
                                </div>
                                <div class="progress-item">
                                    <div class="progress-header">
                                        <span class="progress-name">好感度</span>
                                        <span class="progress-value">${affection}</span>
                                    </div>
                                    <div class="progress-bar-container">
                                        <div class="progress-bar" style="width: ${affectionPercent}%;"></div>
                                    </div>
                                </div>
                                <div class="progress-item">
                                    <div class="progress-header">
                                        <span class="progress-name">恶堕值</span>
                                        <span class="progress-value">${corruption}%</span>
                                    </div>
                                    <div class="progress-bar-container">
                                        <div class="progress-bar" style="width: ${corruptionPercent}%;"></div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    `;
                    heroinesContainer.insertAdjacentHTML('beforeend', cardHTML);
                }

            } catch (error) {
                console.error("状态栏渲染失败:", error);
                const container = document.getElementById('mainContainer');
                container.innerHTML = `
                    <div style="
                        color: var(--text-primary); 
                        padding: var(--space-lg); 
                        text-align: center;
                        background: var(--bg-card);
                        border: 3px solid var(--border-main);
                        box-shadow: 4px 4px 0px var(--shadow-color);
                    ">
                        <h3 style="margin-bottom: var(--space-sm); text-transform: uppercase;">状态栏数据加载失败</h3>
                        <p>${error.message}</p>
                        <p style="margin-top: var(--space-sm); color: var(--text-secondary); font-size: 0.9rem;">
                            这通常发生在第一次对话或刷新页面后，请尝试发送一条新消息以更新状态。
                        </p>
                    </div>
                `;
            } finally {
                // 无论成功与否，都隐藏加载动画
                const loadingOverlay = document.getElementById('loading-overlay');
                loadingOverlay.style.opacity = '0';
                setTimeout(() => loadingOverlay.style.display = 'none', 500);

                // 显示主容器
                const mainContainer = document.getElementById('mainContainer');
                mainContainer.style.opacity = '1';
            }
        });
    </script>
</body>
</html>
